let data;try{data=JSON.parse(localStorage.getItem(key))||structuredClone(sample);if(!Array.isArray(data.projects)||!data.projects.length)throw Error();}catch{data=structuredClone(sample);}migrate(data);
let active=data.projects[0].id,editing=null,creating=null,focusedTask=null,lastFocus=null,nameMode='task',drag=null,panning=false,toastTimer,connection=null,viewZoom={},undoStack=[],redoStack=[];
