function bounds(t,width,surface){const dates=t.events.map(e=>day(visibleDate(e))),start=dates.length?Math.min(...dates):day(today()),end=dates.length?Math.max(...dates):start+14,zoom=viewZoom[surface+':'+t.id]||1,pad=78,span=Math.max(1,end-start),fitScale=Math.max(.001,(width-pad*2)/span),scale=fitScale*zoom,canvasWidth=Math.max(width,pad*2+span*scale);return {start,end,width:canvasWidth,scale,pad,zoom,x:s=>pad+(day(s)-start)*scale};}
function icon(name){return {expand:'⛶',fit:'↔',plus:'＋',minus:'−'}[name];}
