function render(){hideHover();const p=project(),events=p.tasks.flatMap(t=>t.events);$('project-title').textContent=p.name;$('project-description').textContent=p.description||'Your project history, in one place.';$('total-count').textContent=p.tasks.length;$('events-count').textContent=events.length;$('upcoming-count').textContent=events.filter(e=>e.kind==='action'&&!e.done).length;$('completed-count').textContent=events.filter(e=>e.done).length;$('task-count').textContent=p.tasks.length+' tasks';$('project-nav').innerHTML=data.projects.map(x=>`<button class="project-link ${x.id===active?'selected':''}" data-project="${x.id}">${esc(x.name)}</button>`).join('');const labelWidth=innerWidth<700?150:205,width=Math.max(240,$('viewport').clientWidth-labelWidth);$('timeline-content').style.width='100%';$('timeline-content').innerHTML=p.tasks.length?p.tasks.map(t=>`<div class="task-row"><div class="task-label"><div class="task-name">${esc(t.name)}</div><div class="task-meta">${t.events.length} events · ${new Set(t.events.map(e=>e.lane)).size>1?'Parallel paths':'Main path'}</div></div>${taskMarkup(t,width)}</div>`).join(''):'<div class="empty-task">No tasks yet. Add a task to start its timeline.</div>';$('undo').disabled=!undoStack.length;$('redo').disabled=!redoStack.length;}
