$('event-form').onsubmit=ev=>{ev.preventDefault();const description=$('event-description').value.trim(),kind=$('event-kind').value,done=kind==='fact'||$('event-done').checked,occurred=kind==='fact'?$('event-date').value:null,actual=done?$('event-date').value:null,scheduled=kind==='action'?$('event-due').value:occurred,triggered=kind==='action'?$('event-trigger').value:occurred;if(!description||!scheduled||!triggered||done&&!actual)return;const ctx=editing||creating,tid=ctx.tid;let result,valid=commit(()=>{const t=taskBy(tid);if(editing){const existing=t.events.find(e=>e.id===editing.eid);result=updateEvent(t,existing.id,{description,kind,done,occurred,actual,scheduled,triggered,planned:existing.kind==='action'?existing.planned:scheduled});return result.error;}const from=t.events.find(e=>e.id===creating.from),to=t.events.find(e=>e.id===creating.to),branch=$('event-branch').checked&&!to,lane=branch?Math.max(0,...t.events.map(e=>e.lane))+1:(from?.lane||0),id=uid();t.events.push({id,description,kind,done,occurred,triggered,planned:scheduled,scheduled,actual,lane});if(from&&to){const index=t.edges.findIndex(e=>e[0]===from.id&&e[1]===to.id),reverse=t.edges[index]?.[2]||false;if(index>=0)t.edges.splice(index,1);t.edges.push([from.id,id,reverse],[id,to.id,reverse]);}else if(from)t.edges.push([from.id,id]);return validateTask(t);});if(!valid){$('event-warning').textContent='This change was not saved. Check the dates and path order.';$('event-warning').hidden=false;return;}closeEditor();toast(result?.shifted?`Saved · ${result.shifted} upcoming actions shifted by ${Math.abs(result.delta)} days`:'Event saved');};
