$('fit').onclick=()=>{viewZoom={};render();if(focusedTask)renderTaskDialog();};$('pan').onclick=()=>{panning=!panning;$('pan').setAttribute('aria-pressed',panning);document.querySelectorAll('.task-scroll').forEach(n=>n.classList.toggle('panning',panning));};$('undo').onclick=()=>restore('undo');$('redo').onclick=()=>restore('redo');$('close-task').onclick=closeTask;$('task-dialog').addEventListener('cancel',e=>{e.preventDefault();closeTask();});$('close-connection').onclick=()=>$('connection-dialog').close();$('reverse-connection').onclick=()=>{const c={...connection};commit(()=>{const edge=taskBy(c.tid).edges[c.index];edge[2]=!edge[2];});$('connection-dialog').close();toast('Arrow reversed');};
