window.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>7)drag.moved=true;if(drag.kind==='pan'){drag.scroll.scrollLeft=drag.left-dx;drag.scroll.scrollTop=drag.top-dy;}if(drag.kind==='connect'){const r=drag.svg.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top;drag.path.setAttribute('d',`M ${drag.ox} ${drag.oy} C ${drag.ox+40} ${drag.oy}, ${px-40} ${py}, ${px} ${py}`);document.querySelectorAll('.merge-target').forEach(n=>n.classList.remove('merge-target'));const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-event]');if(target&&target.dataset.task===drag.tid&&canConnect(taskBy(drag.tid),drag.from,target.dataset.event))target.querySelector('.event-circle').classList.add('merge-target');}if(drag.kind==='move'&&drag.moved)drag.node.setAttribute('transform',`translate(${dx},0)`);});
window.addEventListener('pointerup',e=>{if(!drag)return;const d=drag;drag=null;document.querySelectorAll('.merge-target').forEach(n=>n.classList.remove('merge-target'));if(d.kind==='connect'){d.path.remove();const t=taskBy(d.tid),from=t.events.find(e=>e.id===d.from),target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-event]');if(d.moved&&target){if(target.dataset.task!==d.tid)toast('Connect events within the same task.');else if(canConnect(t,d.from,target.dataset.event)){commit(()=>{const trial=taskBy(d.tid);trial.edges.push([d.from,target.dataset.event]);return validateTask(trial);});}else toast('That connection already exists or creates a loop.');}else{const b=geometry.get(d.surface+':'+d.tid),r=d.svg.getBoundingClientRect(),date=d.moved?iso(b.start+Math.round((e.clientX-r.left-b.pad)/b.scale)):iso(day(visibleDate(from))+1),branch=d.moved&&Math.abs(e.clientY-d.startY)>40;openEditor(d.tid,null,d.from,branch,d.port,date);}}else if(d.kind==='move'&&d.moved){const t=taskBy(d.tid),ev=t.events.find(e=>e.id===d.eid),g=geometry.get(d.surface+':'+d.tid),delta=Math.round((e.clientX-d.startX)/g.scale);if(delta){const nd=iso(day(visibleDate(ev))+delta);commit(()=>{const result=updateEvent(taskBy(d.tid),d.eid,ev.kind==='fact'?{occurred:nd,actual:nd}:ev.done?{actual:nd}:{scheduled:nd});return result.error;});}else{render();if(focusedTask)renderTaskDialog();}}else if(d.kind==='move'){openEditor(d.tid,d.eid,null,false,d.node);}if(d.moved||d.kind==='move'){const block=ev=>{ev.stopPropagation();ev.preventDefault();};(d.surface==='modal'?$('task-dialog-content'):$('timeline-content')).addEventListener('click',block,{once:true,capture:true});}});
function showCalendar(){const date=$('calendar-date').value,rows=[];for(const p of data.projects)for(const t of p.tasks)for(const e of t.events){if(e.kind==='fact'&&e.occurred===date)rows.push({p,t,e,label:'Recorded'});else if(e.kind==='action'&&e.triggered<=date&&(!e.done||e.actual>=date))rows.push({p,t,e,label:e.done&&e.actual===date?'Completed':e.scheduled===date?'Due today':!e.done&&e.scheduled<date?'Overdue action':'Active action'});} $('calendar-results').innerHTML=rows.length?rows.map(({p,t,e,label})=>`<div class="calendar-entry"><span>${esc(p.name)} / ${esc(t.name)}</span><strong>${esc(e.description)}</strong><small>${label}${e.kind==='action'?' · Due '+dateLabel(e.scheduled):''}</small></div>`).join(''):'<p>No recorded events or active actions on this day.</p>';}
$('calendar-nav').onclick=()=>{$('calendar-date').value=today();showCalendar();$('calendar-dialog').showModal();};$('calendar-date').onchange=showCalendar;$('close-calendar').onclick=()=>$('calendar-dialog').close();
window.addEventListener('keydown',e=>{const typing=e.target.matches('input,textarea,select,[contenteditable]');if((e.ctrlKey||e.metaKey)&&!typing&&(e.key.toLowerCase()==='z'||e.key.toLowerCase()==='y')){e.preventDefault();if(!$('editor').hidden)closeEditor();restore(e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo');}if(e.key==='Escape'){hideHover();if(!$('editor').hidden){e.preventDefault();closeEditor();}if(drag){drag.path?.remove();drag=null;render();if(focusedTask)renderTaskDialog();}}if(e.key==='Tab'&&!$('editor').hidden){const items=[...$('editor').querySelectorAll('button,input,textarea,select')].filter(x=>!x.closest('[hidden]'));const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('pointercancel',()=>{if(drag){drag.path?.remove();drag=null;render();if(focusedTask)renderTaskDialog();}});
let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{render();if(focusedTask)renderTaskDialog();},120);});render();save();
